(() => {
  'use strict';
  const db=window.RESEARCH_DB, $=s=>document.querySelector(s), esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
  const typeNames={all:'全部资料',topic:'选题建议',contest:'竞赛渠道',case:'获奖案例',resource:'数据与工具',major:'专业索引',guide:'研究指南'};
  const glyphs={all:'▦',topic:'◇',contest:'⚑',case:'☆',resource:'⌘',major:'▤',guide:'▧'};
  const params=new URLSearchParams(location.search);
  const tiers=Object.fromEntries(db.difficultyLevels.map(t=>[t.id,t]));
  const state={q:params.get('q')||'',type:params.get('type')||'all',group:params.get('group')||'all',major:params.get('major')||'all',level:params.get('level')||'all',difficulty:params.get('difficulty')||'all',sort:params.get('sort')||'relevance',page:1};
  if(!typeNames[state.type])state.type='all';if(state.group!=='all'&&!db.groups.some(g=>g.id===state.group))state.group='all';if(state.major!=='all'&&!db.majors.some(m=>m.id===state.major))state.major='all';if(!['all','入门','进阶','导师协作'].includes(state.level))state.level='all';if(!['relevance','difficulty','date','title'].includes(state.sort))state.sort='relevance';if(state.difficulty!=='all'&&!tiers[state.difficulty])state.difficulty='all';if(state.difficulty!=='all')state.type='topic';if(state.major!=='all'&&state.group!=='all'&&db.majors.find(m=>m.id===state.major).group!==state.group)state.group='all';
  const normalize=s=>String(s).normalize('NFKC').toLowerCase().replace(/[\s\-_]/g,'');
  const aliases={'riscv':['risc-v','riscv','risc v'],'芯片':['集成电路','芯片','rtl','fpga'],'人工智能':['人工智能','ai','机器学习','tinyml'],'动科':['动物科学','动科'],'动医':['动物医学','动医'],'集成电路':['集成电路','芯片','ic'],'数模':['数学建模','数模'],'毕设':['毕业设计','毕设','选题']};
  const index=db.records.map(r=>({r,text:normalize([r.title,r.summary,...(r.tags||[]),...(r.sections||[]).flatMap(s=>[s.heading,...s.items]),...(r.majors||[]).map(id=>db.majors.find(m=>m.id===id)?.name||''),...(r.sourceIds||[]).map(id=>{const s=db.sources[id];return [s.title,s.org,s.url].join(' ')}),r.level,r.difficulty,tiers[r.difficulty]?.name,...(r.difficultyProfile?[r.difficultyProfile.reason,...r.difficultyProfile.prerequisites,...r.difficultyProfile.resources,r.difficultyProfile.minimum,r.difficultyProfile.stretch]:[]),r.type==='topic'?'毕业设计 毕设 选题':'' ].join(' ')),title:normalize(r.title)}));
  function tokens(){return state.q.trim().split(/\s+/).filter(Boolean).map(t=>{const n=normalize(t);const alias=Object.keys(aliases).find(k=>normalize(k)===n||aliases[k].some(v=>normalize(v)===n));return (alias?aliases[alias]:[t]).map(normalize)})}
  function filtered(forTierCounts=false){const terms=tokens();return index.filter(({r,text})=>(forTierCounts?r.type==='topic':state.type==='all'||r.type===state.type)&&(state.group==='all'||r.groups.includes(state.group))&&(state.major==='all'||r.majors.includes(state.major))&&(state.level==='all'||r.level===state.level)&&(forTierCounts||state.difficulty==='all'||r.difficulty===state.difficulty)&&terms.every(v=>v.some(t=>text.includes(t)))).map(v=>({...v,score:terms.reduce((a,ts)=>a+(ts.some(t=>v.title.includes(t))?15:1),0)+(v.r.priority||0)})).sort((a,b)=>state.sort==='title'?a.r.title.localeCompare(b.r.title,'zh-CN'):state.sort==='date'?b.r.date.localeCompare(a.r.date)||b.score-a.score:state.sort==='difficulty'?(tiers[a.r.difficulty]?.rank||99)-(tiers[b.r.difficulty]?.rank||99)||b.score-a.score:b.score-a.score||a.r.title.localeCompare(b.r.title,'zh-CN'));}
  function difficultyTiers(){const list=filtered(true);$('#difficulty-tiers').innerHTML=db.difficultyLevels.map(t=>{const n=list.filter(v=>v.r.difficulty===t.id).length;return `<button class="tier-button ${t.id.toLowerCase()} ${state.difficulty===t.id?'selected':''}" data-difficulty="${t.id}" aria-pressed="${state.difficulty===t.id}"><span class="tier-title"><b>${t.id}</b>${esc(t.name)}<span>${n}</span></span><small>${esc(t.description)}</small></button>`}).join('')}
  function setDifficulty(value){state.difficulty=value;if(value!=='all')state.type='topic';state.page=1;render()}
  function url(){const p=new URLSearchParams;Object.entries(state).forEach(([k,v])=>{if(k==='page'||v==='all'||(k==='sort'&&v==='relevance')||!v)return;p.set(k,v)});history.replaceState(null,'',location.pathname+(p.size?'?'+p:'')+location.hash)}
  function nav(){
    $('#type-nav').innerHTML=Object.entries(typeNames).map(([id,name])=>`<button class="nav-button ${state.type===id?'active':''}" data-type="${id}" aria-pressed="${state.type===id}"><span class="nav-text"><span class="nav-glyph" aria-hidden="true">${glyphs[id]}</span>${name}</span><span class="nav-count">${id==='all'?db.records.length:db.records.filter(r=>r.type===id).length}</span></button>`).join('');
    $('#group-nav').innerHTML=[{id:'all',name:'所有领域'},...db.groups].map(g=>`<button class="nav-button ${state.group===g.id?'active':''}" data-group="${g.id}" aria-pressed="${state.group===g.id}"><span>${esc(g.name)}</span>${g.id==='all'?'':`<span class="nav-count">${db.majors.filter(m=>m.group===g.id).length}</span>`}</button>`).join('');
    $('#view-label').textContent=typeNames[state.type];
  }
  function majorOptions(){let majors=db.majors.filter(m=>state.group==='all'||m.group===state.group);$('#major-select').innerHTML='<option value="all">所有专业</option>'+db.groups.map(g=>{const ms=majors.filter(m=>m.group===g.id);return ms.length?`<optgroup label="${esc(g.name)}">${ms.map(m=>`<option value="${m.id}">${esc(m.name)}</option>`).join('')}</optgroup>`:''}).join('');$('#major-select').value=state.major;}
  function chips(){const items=[];if(state.q)items.push(['q','关键词：'+state.q]);if(state.group!=='all')items.push(['group',db.groups.find(g=>g.id===state.group).name]);if(state.major!=='all')items.push(['major',db.majors.find(m=>m.id===state.major).name]);if(state.level!=='all')items.push(['level','准备：'+state.level]);if(state.difficulty!=='all')items.push(['difficulty','难度：'+state.difficulty+' '+tiers[state.difficulty].name]);$('#active-filters').innerHTML=items.map(([k,v])=>`<button class="filter-chip" data-clear="${k}" aria-label="清除${esc(v)}">${esc(v)} ×</button>`).join('')}
  function card(r){const ss=r.sourceIds.map(id=>db.sources[id]),tier=tiers[r.difficulty];return `<article class="card"><div class="card-top"><span class="type-badge type-${r.type}">${typeNames[r.type]}</span><span class="stage">${esc(r.level?'准备：'+r.level:r.status||'原始来源')}</span></div><h3><button class="title-button" data-detail="${r.id}">${esc(r.title)}</button></h3>${tier?`<div class="difficulty-row"><span class="difficulty-badge ${tier.id.toLowerCase()}">${tier.id} · ${esc(tier.name)}</span><span class="effort-short">${esc(r.difficultyProfile.effort.split('，')[0])} · 规划估计</span></div>`:''}<p class="card-summary">${esc(r.summary)}</p><div class="tags">${(r.tags||[]).slice(0,4).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><div class="card-bottom"><span class="source-short" title="${esc(ss.map(s=>s.org).join(' · '))}">${r.type==='topic'?'建议依据':'来源'}：${esc(ss[0]?.org||'本次调研')} ${ss.length>1?' +'+(ss.length-1):''}</span><button class="details-link" data-detail="${r.id}" aria-label="查看${esc(r.title)}详情">查看资料 ↗</button></div></article>`;}
  function render(){const list=filtered(),size=12,pages=Math.max(1,Math.ceil(list.length/size));state.page=Math.min(state.page,pages);nav();majorOptions();chips();difficultyTiers();$('#search-input').value=state.q;$('#level-select').value=state.level;$('#difficulty-select').value=state.difficulty;$('#sort-select').value=state.sort;$('#result-count').textContent=list.length;$('#result-title').firstChild.textContent=state.q?'检索结果 ':typeNames[state.type]+' ';$('#result-description').textContent=state.difficulty!=='all'?`${state.difficulty} ${tiers[state.difficulty].name} · 难度筛选仅显示选题`:state.q?`包含「${state.q}」的相关资料`:'分层按钮的数量对应当前专业、关键词与准备条件';$('#cards').innerHTML=list.length?list.slice((state.page-1)*size,state.page*size).map(({r})=>card(r)).join(''):`<div class="empty"><h3>暂未找到匹配资料</h3><p>试着缩短关键词、使用同义词，或放宽专业、难度和准备阶段筛选。</p><button class="page-button" data-reset>清除全部筛选</button></div>`;$('#pagination').innerHTML=list.length>size?`<button class="page-button" data-page="-1" ${state.page===1?'disabled':''}>← 上一页</button><span>第 ${state.page} / ${pages} 页 · ${list.length} 条</span><button class="page-button" data-page="1" ${state.page===pages?'disabled':''}>下一页 →</button>`:'';$('#web-search').href='https://www.bing.com/search?q='+encodeURIComponent((state.q||'毕业设计 竞赛')+' '+(state.major==='all'?'佛山大学':db.majors.find(m=>m.id===state.major).name));url();}
  function reset(){Object.assign(state,{q:'',type:'all',group:'all',major:'all',level:'all',difficulty:'all',sort:'relevance',page:1});render()}
  function rubric(){return `<section class="rubric"><h3>四个维度的分层标准</h3><p>${esc(db.difficultyMethod.rule)}</p><div class="rubric-scroll" tabindex="0" role="region" aria-label="难度维度对照表"><table><caption>每项按 1–4 级评估，取最高项作为项目难度</caption><thead><tr><th scope="col">维度</th>${db.difficultyLevels.map(t=>`<th scope="col">${t.id}<br>${esc(t.name)}</th>`).join('')}</tr></thead><tbody>${db.difficultyDimensions.map(d=>`<tr><th scope="row">${esc(d.name)}</th>${d.criteria.map(v=>`<td>${esc(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="assessment-note">评估版本 ${esc(db.difficultyMethod.version)} · ${esc(db.difficultyMethod.assessed)}。${esc(db.difficultyMethod.note)}</p></section>`}
  function difficultyView(r){if(!r.difficultyProfile)return '';const p=r.difficultyProfile,t=tiers[r.difficulty];return `<section class="difficulty-profile" aria-label="选题难度档案"><div class="profile-heading"><span class="difficulty-badge ${t.id.toLowerCase()}">${t.id} · ${esc(t.name)}</span><span>按当前拟议范围评估</span></div><p class="difficulty-reason"><strong>主要瓶颈：</strong>${esc(p.reason)}</p><div class="dimension-grid">${db.difficultyDimensions.map(d=>`<div class="dimension-card"><div><strong>${esc(d.name)}</strong><b>${p.dimensions[d.id]}<small> / 4</small></b></div><p>${esc(d.criteria[p.dimensions[d.id]-1])}</p></div>`).join('')}</div><h3>先修知识</h3><ul>${p.prerequisites.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><h3>资源条件</h3><ul>${p.resources.map(v=>`<li>${esc(v)}</li>`).join('')}</ul><div class="scope-box"><strong>先做这个最小版本</strong><p>${esc(p.minimum)}</p><strong>再考虑扩展</strong><p>${esc(p.stretch)}</p></div><p class="effort-detail"><strong>规划投入：</strong>${esc(p.effort)}。<br><strong>建议协作：</strong>${esc(p.team)}。</p><p class="assessment-note">调研评估，非学校评级。投入估计以具备先修基础为前提；增加范围或缺少数据、设备时需重新评估。</p><button class="text-button" data-help>查看分层标准与学习路线 ↗</button></section>`}
  function related(r){const items=(r.relatedTopicIds||[]).map(id=>db.records.find(v=>v.id===id));return items.length?`<section><h3>相关起步与延伸方向</h3><div class="related-topics">${items.map(v=>`<button class="related-topic" data-detail="${v.id}"><span class="difficulty-badge ${v.difficulty.toLowerCase()}">${v.difficulty}</span>${esc(v.title)} ↗</button>`).join('')}</div></section>`:''}
  function source(s){return `<div class="source-box"><strong>${esc(s.title)}</strong><div class="source-meta">${esc(s.org)} · ${esc(s.kind)} · 核验 ${esc(s.checked)}</div><a class="source-url" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">${esc(s.url)} ↗</a>${s.access?`<div class="source-status">${esc(s.access)}</div>`:''}<div class="source-action"><span>${esc(s.note||'请以原始页面及最新通知为准')}</span><button class="copy-button" data-copy="${esc(s.url)}">复制网址</button></div></div>`}
  function show(r){$('#detail-kicker').textContent=typeNames[r.type]+' / '+r.id.toUpperCase();$('#detail-content').innerHTML=`<h2 id="detail-title">${esc(r.title)}</h2><p class="lead">${esc(r.summary)}</p><div class="tags">${(r.tags||[]).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div>${r.type==='topic'?'<div class="fact-note">调研建议 · 非学校官方毕设题目。下面的方案和周期是拟议研究路线；来源支持背景、工具或数据，不代表原作者或学院认可本题。性能目标需要实际实验验证。</div>':''}${r.type==='major'?'<div class="fact-note">公开专业栏目索引，页面未明确专业列表对应年份；不作为 2026 年完整招生计划、培养方案或学院现状的证明。</div>':''}${difficultyView(r)}${r.id==='guide-difficulty'?rubric():''}${r.sections.map(s=>`<section><h3>${esc(s.heading)}</h3>${s.items.length===1?`<p>${esc(s.items[0])}</p>`:`<ul>${s.items.map(t=>`<li>${esc(t)}</li>`).join('')}</ul>`}</section>`).join('')}${related(r)}${r.report?`<h3>完整调研材料</h3><div class="dialog-links"><a href="downloads/ic-research.md" download>下载 Markdown 版 ↓</a></div><pre class="report-text">${esc(db.report)}</pre>`:''}<section><h3>${r.type==='topic'?'背景、工具与数据依据':'原始来源'} · ${r.sourceIds.length} 个</h3>${r.sourceIds.map(id=>source(db.sources[id])).join('')}</section><div class="source-meta" style="margin-top:20px">资料整理 ${esc(r.date)} · 可搜索标题、正文、标签、专业、难度、先修知识和来源</div>`;if(!$('#detail-dialog').open)$('#detail-dialog').showModal();$('#detail-dialog').scrollTop=0;}
  function about(){show({id:'about',type:'guide',title:'资料范围与使用说明',summary:'一份围绕佛山大学多专业、兼顾毕设与竞赛的自托管资料快照。',tags:['来源可追溯','本机运行','持续积累'],date:db.date,sourceIds:['fosu-catalog','fosu-charter'],sections:[{heading:'这份资料库收录什么',items:[`${db.majors.length} 个公开专业栏目条目；${db.records.filter(r=>r.type==='topic').length} 个拟议选题；${Object.keys(db.sources).length} 个原始来源。各专业的建议深度不同，集成电路另有完整调研报告。`,'来源主要来自竞赛主办方、教育部门、高校、研究机构、论文作者与开源项目。网站搜索的是经整理的摘要与方案，不保存原文全文。']},{heading:'怎样搜索',items:['支持中文、英文和常见缩写；多个关键词以空格分隔，要求同时匹配。可以结合专业、资料类型、难度和准备阶段筛选；按难度选择时进入选题建议视图。难度分层按钮的数量随专业、关键词与准备阶段变化。','例：RISC-V 验证、动物科学 传感器、食品 质量、交通 仿真、市场调查。来源机构与原始网址也可以搜索。','点击资料标题查看详细方案、来源性质、核验日期与可打开的网址。全网继续检索会跳转至 Bing，检索内容会发送给该外部搜索引擎。']},{heading:'事实与建议的边界',items:['竞赛入口与案例以来源为准。专业匹配、题目名称、项目路线、周期和指标均是本次调研分析，未经过各学院导师立项认可。','当前快照为 '+db.date+'。没有把下一届报名日期、奖金、获奖概率或学校可用设备作为已知事实。历史赛季与正在征集的通知在条目中分别说明。','受限的官网与数据集会标明访问条件；文献、数据和代码使用前需阅读对应许可。']},{heading:'私人使用与更新',items:['本机服务只监听 127.0.0.1，同一台电脑可以访问。无需注册账号，也没有上传到公网。','站内检索在浏览器本地完成；打开原始来源、外部搜索会访问对应网站。关闭本地服务不影响资料文件。','需要更新时可修改项目中的 research-data.json；重新生成 data.js 后刷新网站。没有后台自动抓取或定时更新。']}]})}
  $('#snapshot-date').textContent=db.date;$('#edition-date').textContent=db.date;$('#overview').innerHTML=[[db.majors.length,'专业栏目','跨专业检索'],[db.records.filter(r=>r.type==='topic').length,'选题建议','从基础到进阶'],[db.records.filter(r=>r.type==='contest').length,'竞赛渠道','查看当届规则'],[Object.keys(db.sources).length,'原始来源','网址与核验日期']].map(([n,l,s])=>`<div class="stat"><span class="stat-number">${n}</span><div class="stat-label">${l}<small>${s}</small></div></div>`).join('');$('#quick-search').innerHTML=['RISC-V','TinyML','动物科学','市场调查'].map(t=>`<button type="button" class="quick" data-query="${t}">${t}</button>`).join('');
  $('#search-form').addEventListener('submit',e=>{e.preventDefault();state.q=$('#search-input').value.trim();state.page=1;render()});let debounce;$('#search-input').addEventListener('input',()=>{clearTimeout(debounce);debounce=setTimeout(()=>{state.q=$('#search-input').value.trim();state.page=1;render()},180)});
  $('#major-select').addEventListener('change',e=>{state.major=e.target.value;state.page=1;render()});$('#difficulty-select').addEventListener('change',e=>setDifficulty(e.target.value));$('#difficulty-help').addEventListener('click',()=>show(db.records.find(r=>r.id==='guide-difficulty')));$('#level-select').addEventListener('change',e=>{state.level=e.target.value;state.page=1;render()});$('#sort-select').addEventListener('change',e=>{state.sort=e.target.value;state.page=1;render()});$('#reset').addEventListener('click',reset);$('#about-button').addEventListener('click',about);$('#close-dialog').addEventListener('click',()=>$('#detail-dialog').close());$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close()}});
  document.addEventListener('click',async e=>{const t=e.target.closest('button');if(!t)return;if(t.dataset.type){state.type=t.dataset.type;if(state.type!=='topic')state.difficulty='all';state.page=1;render()}if(t.dataset.difficulty)setDifficulty(state.difficulty===t.dataset.difficulty?'all':t.dataset.difficulty);if(t.hasAttribute('data-help'))show(db.records.find(r=>r.id==='guide-difficulty'));if(t.dataset.group){state.group=t.dataset.group;state.major='all';state.page=1;render()}if(t.dataset.query){state.q=t.dataset.query;state.page=1;render()}if(t.dataset.detail)show(db.records.find(r=>r.id===t.dataset.detail));if(t.hasAttribute('data-reset'))reset();if(t.dataset.clear){state[t.dataset.clear]=t.dataset.clear==='q'?'':'all';if(t.dataset.clear==='group')state.major='all';state.page=1;render()}if(t.dataset.page){state.page+=Number(t.dataset.page);render();$('#results').scrollIntoView({behavior:'smooth',block:'start'})}if(t.dataset.copy){try{await navigator.clipboard.writeText(t.dataset.copy);$('#toast').textContent='已复制来源网址';$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,2000)}catch{$('#toast').textContent='请选中上方网址并复制';$('#toast').hidden=false;setTimeout(()=>$('#toast').hidden=true,3000)}}});
  render();
})();
